def reverse(nums: list[int], left: int, right: int) -> None:
    while left < right:
        nums[left], nums[right] = nums[right], nums[left]
        left += 1
        right -= 1

def rotate(nums: list[int], k: int) -> None:
    n = len(nums)
    if n == 0:
        return
    k %= n
    reverse(nums, 0, n - 1)
    reverse(nums, 0, k - 1)
    reverse(nums, k, n - 1)

def rotate_slicing(nums: list[int], k: int) -> None:
    if nums:
        k %= len(nums)
        nums[:] = nums[-k:] + nums[:-k] if k else nums

for fn in (rotate, rotate_slicing):
    a = [1, 2, 3, 4, 5, 6, 7]
    fn(a, 3)
    assert a == [5, 6, 7, 1, 2, 3, 4]
    b = [-1, -100, 3, 99]
    fn(b, 2)
    assert b == [3, 99, -1, -100]
    c = [1, 2]
    fn(c, 5)                     # k larger than n
    assert c == [2, 1]
    d: list[int] = []
    fn(d, 3)
    assert d == []
    e = [1, 2, 3]
