    assert fn(["flower", "flow", "flight"]) == "fl"
    assert fn(["dog", "racecar", "car"]) == ""
    assert fn([]) == ""
    assert fn(["alone"]) == "alone"
    assert fn(["ab", "a"]) == "a"
    assert fn(["", "abc"]) == ""

